python - <<'PY'
import ast, inspect, textwrap, sys
from pathlib import Path
sys.path.insert(0,'/testbed/lib')
from matplotlib.ticker import _decade_less

tracked={'base','less','x'}
source_lines, start = inspect.getsourcelines(_decade_less)
source=''.join(source_lines)
mod = ast.parse(textwrap.dedent(source))
func = mod.body[0]

reads_by_line={}
defs_by_line={}

def add(d, ln, v):
    d.setdefault(start+ln-1,set()).add(v)

class V(ast.NodeVisitor):
    def visit_Name(self,node):
        if node.id in tracked:
            if isinstance(node.ctx, ast.Load):
                add(reads_by_line,node.lineno,node.id)
            elif isinstance(node.ctx,(ast.Store,ast.Del)):
                add(defs_by_line,node.lineno,node.id)
    def visit_AugAssign(self,node):
        # Ignore same-line augmented-assignment target reads.
        self.visit(node.value)
        if isinstance(node.target, ast.Name) and node.target.id in tracked:
            add(defs_by_line,node.lineno,node.target.id)
        else:
            self.visit(node.target)
    def generic_visit(self,node):
        super().generic_visit(node)

V().visit(func)

pairs=set()
last_def={v:None for v in tracked}
code=_decade_less.__code__

def tracer(frame,event,arg):
    if frame.f_code is code and event=='line':
        ln=frame.f_lineno
        for v in sorted(reads_by_line.get(ln,set())):
            if last_def[v] is not None:
                pairs.add((v,last_def[v],ln))
        for v in sorted(defs_by_line.get(ln,set())):
            last_def[v]=ln
    return tracer

sys.settrace(tracer)
inputs=[(150,10),(100,10),(5,10),(-150,10),(-100,10),(10,2),(16,2),(1000,10),(0.5,10),(50,5),(250,10),(100,3)]
for a,b in inputs:
    _decade_less(a,b)
sys.settrace(None)

print('reads',reads_by_line)
print('defs',defs_by_line)
print('pairs',sorted(pairs,key=lambda t:(t[0],t[1],t[2])))
